--
-- Name: get_admin_metrics_v2026(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_admin_metrics_v2026() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE result JSON;
BEGIN
    SELECT json_build_object(
        'users', (SELECT count(*) FROM public.profiles),
        'posts', (SELECT count(*) FROM public.posts),
        'comments', (SELECT count(*) FROM public.comments),
        'jobs', (SELECT count(*) FROM public.job_posts),
        'courses', (SELECT count(*) FROM public.courses),
        'downloads', (SELECT count(*) FROM public.user_documents),
        'likes', (SELECT COALESCE(sum(likes), 0) FROM public.posts),
        'verified', (SELECT count(*) FROM public.posts WHERE is_verified = true),
        'accesses', (SELECT count(*) FROM public.activity_logs WHERE action IN ('app_launch', 'view_changed'))
    ) INTO result;
    RETURN result;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    VALUES (
        NEW.id,
        COALESCE(NEW.raw_user_meta_data->>'name', NEW.email),
        NEW.raw_user_meta_data->>'avatar_url'
    )
    ON CONFLICT (id) DO NOTHING;
    RETURN NEW;
END;
$$;


--
-- Name: handle_post_gamification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_post_gamification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE public.profiles 
    SET reputation = reputation + 10, points = points + 10 
    WHERE id = NEW.author_id;
    RETURN NEW;
END;
$$;


