--
-- Name: admin_dashboard_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.admin_dashboard_stats AS
 SELECT ( SELECT count(*) AS count
           FROM public.profiles) AS total_users,
    ( SELECT count(*) AS count
           FROM public.posts) AS total_posts,
    ( SELECT count(*) AS count
           FROM public.comments) AS total_comments,
    ( SELECT count(*) AS count
           FROM public.job_posts) AS total_jobs,
    ( SELECT count(*) AS count
           FROM public.user_documents) AS total_downloads,
    ( SELECT count(*) AS count
           FROM public.courses) AS total_courses,
    ( SELECT COALESCE(sum(posts.likes), (0)::bigint) AS "coalesce"
           FROM public.posts) AS total_likes,
    ( SELECT count(*) AS count
           FROM public.posts
          WHERE (posts.is_verified = true)) AS verified_posts,
    ( SELECT count(*) AS count
           FROM public.activity_logs
          WHERE (activity_logs.action = ANY (ARRAY['app_launch'::text, 'view_changed'::text]))) AS app_accesses;


--
-- Name: reports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reports (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reporter_id uuid,
    target_user_id uuid,
    post_id uuid,
    comment_id uuid,
    reason text,
    status text DEFAULT 'pending'::text,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: admin_reports_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.admin_reports_view AS
 SELECT r.id,
    r.reporter_id,
    r.target_user_id,
    r.post_id,
    r.comment_id,
    r.reason,
    r.status,
    r.created_at,
    reporter.name AS reporter_name,
    offender.name AS offender_name,
    COALESCE(p.content, c.content) AS reported_content_text
   FROM ((((public.reports r
     LEFT JOIN public.profiles reporter ON ((r.reporter_id = reporter.id)))
     LEFT JOIN public.profiles offender ON ((r.target_user_id = offender.id)))
     LEFT JOIN public.posts p ON ((r.post_id = p.id)))
     LEFT JOIN public.comments c ON ((r.comment_id = c.id)));


